+            new DiskHealthInfo(randomFrom(HealthStatus.values()), randomFrom(DiskHealthInfo.Cause.values()))
+        );
+        return new FetchHealthInfoCacheAction.Response(new HealthInfo(diskHealthInfoMapCopy));
+    }
+}
